import React from "react";

function Section4() {
  const solarSystemPlanets = [
    "Mercury",
    "Venus",
    "Earth",
    "Mars",
    "Jupiter",
    "Saturn",
    "Uranus",
    "Neptune",
  ];

  return (
    <div className=" bg-">
      <ol style={{ listStyleType: "decimal" }} >
        <li className=" text-white" >Mercury</li>
        <li>Venus</li>
        <li>Earth</li>
        <li>Mars</li>
        <li>Jupiter</li>
        <li>Saturn</li>
        <li>Uranus</li>
        <li>Neptune</li>
      </ol>
    </div>
  );
}

export default Section4;
